/* O que a sonda precisa saber. Só o telefone tem de ser preenchido à
   mão: abra um pedido do Arquivo na Base e copie o telefone do cliente.
   Deixando vazio, o teste do telefone é pulado e os outros dois rodam. */
return [{ json: {
  numeroArquivado: '37136684',      // pedido que ESTÁ no Arquivo
  telefone: '',                     // telefone do cliente desse pedido
  desde: '2024-01-01'               // até onde procurar nota fiscal
} }];

/* TRÊS PORTAS, TRÊS RESPOSTAS

   O getOrders já foi descartado nas quatro formas possíveis. Restam três
   métodos que tocam em pedido por outro caminho. Cada um responde sozinho:
   se qualquer um alcançar o Arquivo, some a exportação manual.

   A regra do veredito é a mesma da sonda anterior, e existe por causa da
   armadilha desta API: parâmetro que ela não reconhece NÃO dá erro, ela
   devolve dados como se o filtro tivesse funcionado. Então nada aqui conta
   como sucesso por vir "algum dado" — só conta se vier O PEDIDO PEDIDO. */
const d = $('Dados da sonda').first().json;
const alvo = String(d.numeroArquivado || '');
const out = { pedidoArquivado: alvo };

function resp(no) {
  try { return $(no).first().json || {}; } catch (e) { return { _naoRodou: true }; }
}

// ── 1. Busca por telefone ────────────────────────────────────────────
const tel = resp('Base · pedidos por telefone');
if (!String(d.telefone || '').trim()) {
  out.porTelefone = 'PULADO — preencha o telefone em "Dados da sonda"';
} else if (tel.status !== 'SUCCESS') {
  out.porTelefone = 'RECUSOU — ' + (tel.error_message || tel.error_code || '');
} else {
  const lista = tel.orders || [];
  const achou = lista.some(p => String(p.order_id) === alvo);
  out.porTelefone = achou
    ? 'ALCANÇA — a busca por telefone devolve pedido do Arquivo'
    : 'não alcança (' + lista.length + ' pedido(s) vieram, nenhum é o arquivado)';
}

// ── 2. Diário de eventos ─────────────────────────────────────────────
const jr = resp('Base · diário do pedido');
if (jr.status !== 'SUCCESS') {
  out.porDiario = 'RECUSOU — ' + (jr.error_message || jr.error_code || '');
} else {
  const logs = jr.logs || [];
  const doAlvo = logs.filter(l => String(l.order_id) === alvo);
  out.porDiario = doAlvo.length
    ? 'CONHECE — o diário tem ' + doAlvo.length + ' evento(s) do pedido arquivado'
    : 'não conhece (' + logs.length + ' evento(s) vieram, nenhum do arquivado)';
}

// ── 3. Notas fiscais ─────────────────────────────────────────────────
const nf = resp('Base · notas fiscais');
if (nf.status !== 'SUCCESS') {
  out.porNotaFiscal = 'RECUSOU — ' + (nf.error_message || nf.error_code || '');
} else {
  const notas = nf.invoices || [];
  const doAlvo = notas.some(n => String(n.order_id) === alvo);
  /* Quantas notas são anteriores ao corte de 3 meses: é o que diria se
     esta porta cobre o Arquivo, mesmo sem trazer o pedido exato. */
  const corte = Math.floor(Date.now() / 1000) - 92 * 86400;
  const antigas = notas.filter(n => Number(n.date_add || n.date_sell || 0) < corte).length;
  out.porNotaFiscal = doAlvo
    ? 'ALCANÇA — a nota do pedido arquivado veio'
    : (antigas
        ? 'PARCIAL — ' + antigas + ' de ' + notas.length + ' notas são anteriores ao corte de 3 meses'
        : 'não alcança (' + notas.length + ' nota(s), nenhuma antes do corte)');
}

const ganhou = /ALCANÇA/.test(out.porTelefone) || /ALCANÇA|PARCIAL/.test(out.porNotaFiscal);
out.conclusao = ganhou
  ? 'Alguma porta abriu — me manda esta saída que eu monto o fluxo.'
  : 'As três fecharam. O Arquivo só sai pelo CSV da tela da Base.';
return [{ json: out }];
